'use strict';
window.REAL_DATABASE=true;
window.api=async function(url,options={}){const csrf=document.cookie.split('; ').find(v=>v.startsWith('sales_csrftoken='))?.split('=')[1];const headers={...options.headers};if(options.method&&options.method!=='GET')headers['X-CSRFToken']=csrf||'';const response=await fetch(url,{...options,headers});let value;try{value=await response.json();}catch{throw Error('Ошибка ответа сервера. Обновите страницу.');}if(response.status===401){location.replace('/login/?next='+encodeURIComponent(location.pathname+location.search));throw Error('Требуется повторный вход.');}if(!response.ok)throw Error(value.error||'Не удалось выполнить запрос.');return value;};
function loadScript(src){return new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=src;s.onload=resolve;s.onerror=reject;document.head.append(s);});}
async function initialize(){try{const [payload,summary]=await Promise.all([api('/api/contacts/page?page_size=10'),api('/api/contacts/summary')]);window.INITIAL_PAGE=payload;window.CONTACT_SUMMARY=summary;window.CONTACTS=payload.contacts;window.AUDIENCES=payload.audiences;const audienceSelect=document.getElementById('audience');audienceSelect.replaceChildren(new Option('Все аудитории',''));payload.audiences.forEach(a=>audienceSelect.add(new Option(a.label,String(a.id))));const sourceSelect=document.getElementById('source');sourceSelect.replaceChildren(new Option('Все источники',''));summary.sources.forEach(s=>sourceSelect.add(new Option(s,s)));await loadScript('/app.js');await loadScript('/details.js');await loadScript('/phones-ui.js');installPhones();await loadScript('/tags.js');await loadScript('/profile-ui.js');installProfileUI();await loadScript('/collection.js');await loadScript('/eondiris.js');await loadScript('/source-layout.js');await loadScript('/gov.js');await loadScript('/dfo.js');await loadScript('/overshop.js');await loadScript('/kaspi.js');await loadScript('/template-builder.js');await loadScript('/template-mail.js');await loadScript('/template-tools.js');await loadScript('/templates.js');await loadScript('/email-policy.js');await loadScript('/campaign-approval.js');await loadScript('/campaigns.js');await loadScript('/campaign-queue.js');await loadScript('/campaign-statistics.js');await loadScript('/campaign-readiness.js');await loadScript('/subscriptions.js');await loadScript('/activity-audiences.js');await loadScript('/servercore.js');await loadScript('/campaign-mail-check.js');await loadScript('/automations.js');await loadScript('/rehearsals.js');await loadScript('/frequency.js');await loadScript('/action-journal.js');await loadScript('/notifications.js');document.querySelector('.version').textContent='ЭТАП 2.2c';document.querySelector('.demo').innerHTML='<b>Локальная база данных</b><span>Контакты и аудитории сохраняются на этом компьютере. Goszakup доступен в разделе «Сбор данных». Доставка ещё не подключена.</span>';document.querySelectorAll('.table-tools>span').forEach(el=>el.textContent='События доставки ещё не подключены');document.querySelectorAll('.stats small')[0].textContent='Постоянная база контактов';const toolbar=document.querySelector('.heading');const importButton=document.createElement('button');importButton.className='outline';importButton.textContent='Импорт CSV / Excel';toolbar.append(importButton);const importDialog=document.createElement('dialog');importDialog.className='client-dialog';importDialog.innerHTML='<div class="dialog-heading"><h2>Импорт клиентов</h2><button type="button" class="outline" id="close-import">Закрыть</button></div><p>Форматы: CSV, XLS, XLSX. До 2 МБ и 10 000 строк. Excel: читается первый лист, первая строка — заголовки. CSV: UTF-8, разделитель ; или запятая.<table class="import-columns"><thead><tr><th>Столбец</th><th>Заголовок</th><th>Обязательный</th><th>Пример</th></tr></thead><tbody><tr><td>A / 1</td><td>Компания</td><td>Да</td><td>Название организации / ФИО</td></tr><tr><td>B / 2</td><td>Email</td><td>Нет</td><td>contact@example.com</td></tr><tr><td>C / 3</td><td>Источник</td><td>Нет</td><td>Выставка</td></tr><tr><td>D / 4</td><td>URL</td><td>Нет</td><td>https://example.com/contacts</td></tr><tr><td>E / 5</td><td>Телефон</td><td>Нет</td><td>+7… (несколько через |)</td></tr></tbody></table><table class="import-columns"><thead><tr><th>Дополнительный столбец</th><th>Формат</th></tr></thead><tbody><tr><td>БИН</td><td>12 цифр; пусто для физлиц</td></tr><tr><td>Город</td><td>Название города</td></tr><tr><td>Сайт</td><td>https://…; несколько через |</td></tr><tr><td>Соцсети</td><td>Telegram=@name | Instagram=https://…</td></tr><tr><td>Отрасль</td><td>Вид деятельности</td></tr><tr><td>Тип организации</td><td>Тип учреждения</td></tr><tr><td>Теги</td><td>Через пробел: #опт #партнёр</td></tr><tr><td>Контактное лицо; Должность; Email контакта; Телефон контакта</td><td>Четыре отдельных необязательных столбца</td></tr></tbody></table><small>Рекомендуемый порядок: Компания → Email → Источник → URL → Телефон. Поля определяются по заголовкам; обязательна только Компания. Необязательные можно пропустить. Один email в строке. Аудиторию выбирайте ниже — основной раздел или подкатегорию.</small></p><p>БИН связывает данные с существующей организацией. Для повторного импорта без БИН используется пара название + email. Без БИН и email запись не объединяется по имени: повторный файл может создать отдельного клиента.</p><p><a href="/sample.csv" download>Скачать пример CSV</a></p><form id="import-form"><label>Аудитория<select id="import-audience" required></select></label><label>Файл<input id="import-file" type="file" accept=".csv,.xls,.xlsx,text/csv,application/vnd.ms-excel,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" required></label><button class="outline" type="submit">Проверить и показать предпросмотр</button></form><div id="import-result" role="status"></div><button id="commit-import" class="outline" hidden>Подтвердить импорт</button>';document.body.append(importDialog);payload.audiences.forEach(a=>document.getElementById('import-audience').add(new Option(a.label,a.id)));let token=null;importButton.addEventListener('click',()=>importDialog.showModal());document.getElementById('close-import').onclick=()=>importDialog.close();document.getElementById('import-file').onchange=()=>{token=null;document.getElementById('commit-import').hidden=true;document.getElementById('import-result').replaceChildren();};document.getElementById('import-audience').onchange=()=>{token=null;document.getElementById('commit-import').hidden=true;};document.getElementById('import-form').onsubmit=async event=>{event.preventDefault();token=null;document.getElementById('commit-import').hidden=true;const result=document.getElementById('import-result');result.textContent='Проверка…';const form=new FormData();form.append('file',document.getElementById('import-file').files[0]);form.append('audience',document.getElementById('import-audience').value);try{const report=await api('/api/import/preview',{method:'POST',body:form});token=report.token;result.replaceChildren();const summary=document.createElement('p');summary.textContent=`Корректных строк: ${report.stats.valid}. Новых контактов: ${report.stats.new_contacts}. Без устойчивого ключа: ${report.stats.unidentified||0}. Дублей строк: ${report.stats.duplicates}. Ошибок: ${report.stats.errors}.`;result.append(summary);for(const err of report.errors){const p=document.createElement('p');p.textContent=`Строка ${err.line}: ${err.error}`;result.append(p);}const table=document.createElement('table');for(const row of report.preview){const tr=document.createElement('tr');for(const value of [row.name,row.email,row.source]){const td=document.createElement('td');td.textContent=value;tr.append(td);}table.append(tr);}result.append(table);document.getElementById('commit-import').hidden=!report.can_commit;}catch(error){result.textContent=error.message;}};document.getElementById('commit-import').onclick=async event=>{event.target.disabled=true;try{const result=await api('/api/import/commit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token})});document.getElementById('import-result').textContent=`Добавлено: ${result.created}. Уже существовали: ${result.updated}. Перезагрузка…`;location.reload();}catch(error){document.getElementById('import-result').textContent=error.message;event.target.disabled=false;}};const createButton=document.createElement('button');createButton.className='outline';createButton.textContent='Добавить подкатегорию';audiencePage.querySelector('.heading').append(createButton);createButton.onclick=()=>{const d=document.createElement('dialog');d.className='client-dialog';d.innerHTML='<h2>Новая подкатегория</h2><form><label>Основная группа<select name="parent_id" required></select></label><label>Название<input name="name" maxlength="120" required></label><div class="actions"><button class="outline">Создать</button><button type="button" class="outline">Отмена</button></div><p role="status"></p></form>';document.body.append(d);d.querySelector('[type=button]').onclick=()=>d.close();d.addEventListener('close',()=>d.remove());d.querySelector('form').onsubmit=async e=>{e.preventDefault();const name=new FormData(e.target).get('name');try{await api('/api/audiences',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,parent_id:new FormData(e.target).get('parent_id')})});sessionStorage.setItem('open-audiences','1');location.reload();}catch(error){d.querySelector('[role=status]').textContent=error.message;}};payload.audiences.filter(a=>!a.parent_id).forEach(a=>d.querySelector('[name=parent_id]').add(new Option(a.name,a.id)));d.showModal();};audiencePage.querySelector('.demo').innerHTML='<b>Постоянные аудитории</b><span>Создайте группу и выберите её при импорте CSV. Изменения сохраняются в БД.</span>';if(sessionStorage.getItem('open-audiences')){sessionStorage.removeItem('open-audiences');showPage(true);}}catch(error){document.querySelector('.demo').textContent='Не удалось загрузить БД: '+error.message;}}
initialize();


